<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#D19A66;">    MIN_VALUE</span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;"> +=</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 1</span></span>
